def flatten_dict(d, sep="."):
    out = {}
    def walk(node, prefix):
        for k, v in node.items():
            path = f"{prefix}{sep}{k}" if prefix else k
            if isinstance(v, dict) and v:
                walk(v, path)
            else:
                out[path] = v
    walk(d, "")
    return out

